const BUSINESS_ENQUIRY_HEADERS = [
  'created_at',
  'phone',
  'name',
  'enquiry_type',
  'profession',
  'brand_name',
  'insta_handle',
  'insta_url',
  'raw_message',
  'status',
  'notes',
  'collab_type',
];

async function ensureBusinessEnquiriesSheet(env) {
  let rows;

  try {
    rows = await getSheetValues(
      env,
      'Business Enquiries'
    );
  } catch (e) {
    const message = String(
      e?.message || e
    );

    if (
      !/Unable to parse range/i.test(
        message
      )
    ) {
      throw e;
    }

    await googleSheetsRequest(
      env,
      'POST',
      ':batchUpdate',
      {
        requests: [
          {
            addSheet: {
              properties: {
                title:
                  'Business Enquiries',
              },
            },
          },
        ],
      }
    );

    rows = [];
  }

  if (!rows.length) {
    await updateSheetRow(
      env,
      'Business Enquiries',
      1,
      BUSINESS_ENQUIRY_HEADERS
    );

    return [
      BUSINESS_ENQUIRY_HEADERS,
    ];
  }

  const header = [
    ...(rows[0] || []),
  ];

  if (
    safeText(
      header[11]
    ).trim() !== 'collab_type'
  ) {
    while (
      header.length < 12
    ) {
      header.push('');
    }

    header[11] =
      'collab_type';

    await updateSheetRow(
      env,
      'Business Enquiries',
      1,
      header
    );

    rows[0] = header;
  }

  return rows;
}

async function appendBusinessEnquiryToSheets(
  env,
  data
) {
  try {
    const rows =
      await ensureBusinessEnquiriesSheet(
        env
      );

    const row = [
      safeText(data.created_at),
      safeText(data.phone),
      safeText(data.name),
      safeText(data.enquiry_type),
      safeText(data.profession),
      safeText(data.brand_name),
      safeText(data.insta_handle),
      safeText(data.insta_url),
      safeText(data.raw_message),
      safeText(data.status),
      safeText(data.notes),
      safeText(data.collab_type),
    ];

    for (
      let i = rows.length - 1;
      i >= 1;
      i--
    ) {
      const existing =
        rows[i] || [];

      if (
        safeText(existing[1]) ===
          safeText(data.phone) &&
        safeText(existing[9]) ===
          'started'
      ) {
        const updatedRow = [
          ...row,
        ];

        updatedRow[0] =
          safeText(existing[0]) ||
          safeText(
            data.created_at
          );

        await updateSheetRow(
          env,
          'Business Enquiries',
          i + 1,
          updatedRow
        );

        return;
      }
    }

    await appendSheetRow(
      env,
      'Business Enquiries',
      row
    );
  } catch (e) {
    console.error(
      'Business Enquiries sheet error:',
      e
    );
  }
}

