function parseOrderItemsForPacking(itemsRaw) {
  try {
    const items = typeof itemsRaw === 'string'
      ? JSON.parse(itemsRaw || '[]')
      : (itemsRaw || []);

    return Array.isArray(items) ? items : [];
  } catch {
    return [];
  }
}

function parseProductImagesForPacking(product) {
  let images = [];

  try {
    images = typeof product.images === 'string'
      ? JSON.parse(product.images || '[]')
      : (product.images || []);
  } catch {
    images = [];
  }

  if (!Array.isArray(images)) images = [];

  if (product.image_url && !images.includes(product.image_url)) {
    images.unshift(product.image_url);
  }

  return images.filter(Boolean);
}

async function enrichOrderForPacking(env, order) {
  const items = parseOrderItemsForPacking(order.items);

  const skus = [...new Set(
    items
      .map(i => String(i.sku || i.product_sku || i.id || '').trim())
      .filter(Boolean)
  )];

  if (!skus.length) {
    return { ...order, items };
  }

  const placeholders = skus.map(() => '?').join(',');

  const { results } = await env.DB.prepare(`
    SELECT sku, name, category, price, image_url, images, website_link
    FROM products
    WHERE sku IN (${placeholders})
  `).bind(...skus).all();

  const productMap = {};
  for (const p of (results || [])) {
    productMap[String(p.sku)] = p;
  }

  const packedItems = items.map(item => {
    const sku = String(item.sku || item.product_sku || item.id || '').trim();
    const product = productMap[sku] || null;
    const productImages = product ? parseProductImagesForPacking(product) : [];

    return {
      ...item,
      sku,
      name: item.name || product?.name || sku || 'Jewellery',
      category: item.category || product?.category || '',
      price: Number(item.price || product?.price || 0),
      qty: Number(item.qty || item.quantity || 1),

      product_image_url:
        item.product_image_url ||
        item.image_url ||
        item.image ||
        productImages[0] ||
        '',

      product_images: productImages,
      product_page_url: product?.website_link || ''
    };
  });

  return {
    ...order,
    items: packedItems
  };
}

function cleanReturnText(value, maxLength = 500) {
  return String(value ?? '')
    .trim()
    .slice(0, maxLength);
}

function parseReturnEvidence(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => cleanReturnText(item, 1000))
    .filter((item) => /^https?:\/\//i.test(item))
    .slice(0, 10);
}

function parseReturnJsonArray(value) {
  try {
    const parsed =
      typeof value === 'string'
        ? JSON.parse(value || '[]')
        : value;

    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return [];
  }
}

const CUSTOMER_RETURN_WINDOW_DAYS = 7;

const CUSTOMER_RETURN_WINDOW_MS =
  CUSTOMER_RETURN_WINDOW_DAYS *
  24 *
  60 *
  60 *
  1000;

const CLOSED_RETURN_REQUEST_STATUSES =
  new Set([
    'rejected',
    'refunded',
    'completed',
    'cancelled',
  ]);

function parseD1DateMilliseconds(value) {
  const text = cleanReturnText(
    value,
    100
  );

  if (!text) {
    return Number.NaN;
  }

  const normalized =
    /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(
      text
    )
      ? `${text.replace(' ', 'T')}Z`
      : text;

  return Date.parse(normalized);
}

function isOpenReturnRequestStatus(value) {
  const status = cleanReturnText(
    value,
    50
  ).toLowerCase();

  return Boolean(status) &&
    !CLOSED_RETURN_REQUEST_STATUSES.has(
      status
    );
}

function getPurchaseReturnEligibility(order) {
  const status = cleanReturnText(
    order?.status,
    50
  ).toLowerCase();

  const paymentStatus =
    cleanReturnText(
      order?.payment_status,
      50
    ).toLowerCase();

  const deliveredTime =
    parseD1DateMilliseconds(
      order?.delivered_at
    );

  const expiresTime =
    Number.isFinite(deliveredTime)
      ? deliveredTime +
        CUSTOMER_RETURN_WINDOW_MS
      : Number.NaN;

  const expiresAt =
    Number.isFinite(expiresTime)
      ? new Date(
          expiresTime
        ).toISOString()
      : null;

  const daysRemaining =
    Number.isFinite(expiresTime)
      ? Math.max(
          0,
          Math.ceil(
            (
              expiresTime -
              Date.now()
            ) /
            (
              24 *
              60 *
              60 *
              1000
            )
          )
        )
      : 0;

  if (paymentStatus !== 'paid') {
    return {
      eligible: false,
      reason:
        'Return or exchange is available only after payment',
      code:
        'payment_not_completed',
      expiresAt,
      daysRemaining,
    };
  }

  if (
    status === 'cancelled' ||
    status === 'returned' ||
    paymentStatus === 'refunded'
  ) {
    return {
      eligible: false,
      reason:
        'This order is already closed',
      code:
        'order_closed',
      expiresAt,
      daysRemaining,
    };
  }

  if (status !== 'delivered') {
    return {
      eligible: false,
      reason:
        'Return or exchange is available only after delivery',
      code:
        'order_not_delivered',
      expiresAt,
      daysRemaining,
    };
  }

  if (!Number.isFinite(deliveredTime)) {
    return {
      eligible: false,
      reason:
        'Delivery date is unavailable',
      code:
        'delivery_date_missing',
      expiresAt,
      daysRemaining,
    };
  }

  if (Date.now() > expiresTime) {
    return {
      eligible: false,
      reason:
        'Seven-day return or exchange window from the delivery date has expired',
      code:
        'return_window_expired',
      expiresAt,
      daysRemaining: 0,
    };
  }

  return {
    eligible: true,
    reason: '',
    code: 'eligible',
    expiresAt,
    daysRemaining,
  };
}

function generateReturnRequestId() {
  const date = new Date()
    .toISOString()
    .slice(0, 10)
    .replace(/-/g, '');

  const random = crypto.randomUUID()
    .replace(/-/g, '')
    .slice(0, 8)
    .toUpperCase();

  return `KRE-${date}-${random}`;
}

function buildReturnRequestItems(order, body) {
  const orderItems = parseOrderItemsForPacking(order.items);

  if (!Array.isArray(orderItems) || orderItems.length === 0) {
    return {
      success: false,
      status: 409,
      error: 'Order does not contain returnable items',
    };
  }

  const requestScope =
    body.request_scope === 'full_order'
      ? 'full_order'
      : 'items';

  const rawRequestedItems =
    requestScope === 'full_order'
      ? orderItems.map((item, index) => ({
          line_index: index,
          quantity: Number(
            item.qty ??
            item.quantity ??
            1
          ),
        }))
      : Array.isArray(body.items)
          ? body.items
          : [];

  if (rawRequestedItems.length === 0) {
    return {
      success: false,
      status: 400,
      error: 'At least one return item is required',
    };
  }

  const selectedItems = [];
  const usedIndexes = new Set();

  for (const requestedItem of rawRequestedItems) {
    let lineIndex = Number(
      requestedItem?.line_index
    );

    if (
      !Number.isInteger(lineIndex) ||
      lineIndex < 0 ||
      lineIndex >= orderItems.length
    ) {
      const requestedSku = cleanReturnText(
        requestedItem?.sku,
        100
      ).toUpperCase();

      lineIndex = orderItems.findIndex(
        (orderItem, index) =>
          !usedIndexes.has(index) &&
          cleanReturnText(
            orderItem?.sku ??
            orderItem?.product_sku ??
            orderItem?.id,
            100
          ).toUpperCase() === requestedSku
      );
    }

    if (
      lineIndex < 0 ||
      lineIndex >= orderItems.length
    ) {
      return {
        success: false,
        status: 400,
        error: 'Selected item does not belong to this order',
      };
    }

    if (usedIndexes.has(lineIndex)) {
      return {
        success: false,
        status: 400,
        error: `Order line ${lineIndex} was selected more than once`,
      };
    }

    const orderItem = orderItems[lineIndex];

    const orderedQuantity = Math.max(
      1,
      Math.floor(
        Number(
          orderItem.qty ??
          orderItem.quantity ??
          1
        )
      )
    );

    const requestedQuantity = Math.floor(
      Number(
        requestedItem?.quantity ??
        requestedItem?.qty ??
        orderedQuantity
      )
    );

    if (
      !Number.isFinite(requestedQuantity) ||
      requestedQuantity <= 0 ||
      requestedQuantity > orderedQuantity
    ) {
      return {
        success: false,
        status: 400,
        error:
          `Invalid quantity for order line ${lineIndex}. ` +
          `Maximum allowed: ${orderedQuantity}`,
      };
    }

    const sku = cleanReturnText(
      orderItem.sku ??
      orderItem.product_sku ??
      orderItem.id,
      100
    );

    if (!sku) {
      return {
        success: false,
        status: 409,
        error: `SKU missing for order line ${lineIndex}`,
      };
    }

    usedIndexes.add(lineIndex);

    selectedItems.push({
      lineIndex,
      sku,
      productName: cleanReturnText(
        orderItem.name ??
        orderItem.product_name ??
        sku,
        300
      ),
      quantity: requestedQuantity,
      unitPrice: Math.max(
        0,
        Number(orderItem.price ?? 0)
      ),
      replacementSku: cleanReturnText(
        requestedItem?.replacement_sku,
        100
      ) || null,
      replacementName: cleanReturnText(
        requestedItem?.replacement_name,
        300
      ) || null,
      replacementUnitPrice:
        requestedItem?.replacement_unit_price == null
          ? null
          : Math.max(
              0,
              Number(
                requestedItem.replacement_unit_price
              )
            ),
      conditionNote: cleanReturnText(
        requestedItem?.condition_note,
        1000
      ),
      evidenceUrls: parseReturnEvidence(
        requestedItem?.evidence_urls
      ),
    });
  }

  return {
    success: true,
    requestScope,
    items: selectedItems,
  };
}

async function handleCreateReturnRequest(
  orderId,
  request,
  env,
  options = {}
) {
  const body =
    options.body ??
    await request
      .json()
      .catch(() => ({}));

  const order =
    options.order ??
    await env.DB.prepare(`
      SELECT *
      FROM orders
      WHERE order_id = ?
      LIMIT 1
    `)
      .bind(orderId)
      .first();

  if (!order) {
    return errorResponse(
      'Order not found',
      404
    );
  }

  const requestType =
    cleanReturnText(
      body.request_type,
      20
    ).toLowerCase();

  if (
    requestType !== 'return' &&
    requestType !== 'exchange'
  ) {
    return errorResponse(
      'request_type must be return or exchange',
      400
    );
  }

  const reasonCode =
    cleanReturnText(
      body.reason_code || 'other',
      50
    ).toLowerCase();

  const reasonText =
    cleanReturnText(
      body.reason_text,
      1000
    );

  const customerNote =
    cleanReturnText(
      body.customer_note,
      2000
    );

  if (
    !reasonText &&
    reasonCode === 'other'
  ) {
    return errorResponse(
      'Return or exchange reason is required',
      400
    );
  }

  const ownerOverride =
    options.allowOwnerOverride !== false &&
    body.owner_override === true;

  const eligibility =
    getPurchaseReturnEligibility(
      order
    );

  if (
    !ownerOverride &&
    !eligibility.eligible
  ) {
    return errorResponse(
      eligibility.reason,
      409
    );
  }

  const existingRequest =
    await env.DB.prepare(`
      SELECT
        request_id,
        status
      FROM return_requests
      WHERE order_id = ?
        AND status NOT IN (
          'rejected',
          'refunded',
          'completed',
          'cancelled'
        )
      ORDER BY id DESC
      LIMIT 1
    `)
      .bind(orderId)
      .first();

  if (existingRequest) {
    return errorResponse(
      `Open request already exists: ` +
      `${existingRequest.request_id}`,
      409
    );
  }

  const itemResult =
    buildReturnRequestItems(
      order,
      body
    );

  if (!itemResult.success) {
    return errorResponse(
      itemResult.error,
      itemResult.status
    );
  }

  const requestId =
    generateReturnRequestId();

  const evidenceUrls =
    parseReturnEvidence(
      body.evidence_urls
    );

  const reverseShippingFee =
    Math.max(
      0,
      Number(
        options.fixedReverseShippingFee ??
        body.reverse_shipping_fee ??
        60
      )
    );

  const statements = [
    env.DB.prepare(`
      INSERT INTO return_requests (
        request_id,
        order_id,
        phone,
        customer_name,
        request_type,
        request_scope,
        reason_code,
        reason_text,
        customer_note,
        evidence_urls_json,
        status,
        reverse_shipping_fee,
        payment_id,
        refund_status,
        refund_gateway,
        refund_method,
        refund_currency,
        requested_at,
        created_at,
        updated_at
      ) VALUES (
        ?, ?, ?, ?, ?, ?,
        ?, ?, ?, ?,
        'requested',
        ?,
        ?,
        'not_started',
        '',
        'original_payment',
        'INR',
        datetime('now'),
        datetime('now'),
        datetime('now')
      )
    `).bind(
      requestId,
      orderId,
      cleanReturnText(
        order.phone,
        30
      ),
      cleanReturnText(
        order.customer_name,
        300
      ),
      requestType,
      itemResult.requestScope,
      reasonCode,
      reasonText,
      customerNote,
      JSON.stringify(
        evidenceUrls
      ),
      reverseShippingFee,
      cleanReturnText(
        order.payment_id,
        200
      ) || null
    ),

    env.DB.prepare(`
      UPDATE orders
      SET
        return_requested = 1,
        return_reason = ?,
        return_requested_at =
          datetime('now'),
        updated_at =
          datetime('now')
      WHERE order_id = ?
    `).bind(
      reasonText || reasonCode,
      orderId
    ),
  ];

  for (
    const item of itemResult.items
  ) {
    statements.push(
      env.DB.prepare(`
        INSERT INTO return_request_items (
          request_id,
          order_id,
          line_index,
          sku,
          product_name,
          quantity,
          unit_price,
          replacement_sku,
          replacement_name,
          replacement_unit_price,
          condition_note,
          evidence_urls_json,
          created_at,
          updated_at
        ) VALUES (
          ?, ?, ?, ?, ?, ?, ?,
          ?, ?, ?, ?, ?,
          datetime('now'),
          datetime('now')
        )
      `).bind(
        requestId,
        orderId,
        item.lineIndex,
        item.sku,
        item.productName,
        item.quantity,
        item.unitPrice,
        item.replacementSku,
        item.replacementName,
        item.replacementUnitPrice,
        item.conditionNote,
        JSON.stringify(
          item.evidenceUrls
        )
      )
    );
  }

  await env.DB.batch(
    statements
  );

  const eventSource =
    cleanReturnText(
      options.eventSource ||
      'admin',
      50
    ) || 'admin';

  await logOrderEvent(
    env,
    orderId,
    requestType === 'return'
      ? 'return_requested'
      : 'exchange_requested',
    `${requestType} request ` +
    `${requestId} created`,
    {
      requestId,
      requestType,
      requestScope:
        itemResult.requestScope,
      itemCount:
        itemResult.items.length,
      reasonCode,
      returnExpiresAt:
        eligibility.expiresAt,
    },
    eventSource
  );

  if (
    options.notifyCustomer === true
  ) {
    const typeLabel =
      requestType === 'exchange'
        ? 'Exchange'
        : 'Return';

    const customerName =
      cleanReturnText(
        order.customer_name ||
        'Customer',
        300
      );

    try {
      await sendWhatsAppText(
        env,
        order.phone,
        `*${typeLabel} Request Received*\n\n` +
        `Hi ${customerName},\n\n` +
        `Order: *${orderId}*\n` +
        `Request ID: *${requestId}*\n` +
        `Status: Requested\n\n` +
        `Our team will review the request before pickup, exchange, or refund action.\n` +
        `Reverse shipping fee: ₹${reverseShippingFee}\n\n` +
        `KAAPAV Fashion Jewellery`
      );
    } catch (
      notificationError
    ) {
      console.error(
        'RETURN_CUSTOMER_NOTIFICATION_FAILED',
        requestId,
        notificationError?.message ||
        notificationError
      );
    }

    try {
      await sendWhatsAppText(
        env,
        env.OWNER_PHONE,
        `*New ${typeLabel} Request*\n\n` +
        `Order: *${orderId}*\n` +
        `Request ID: *${requestId}*\n` +
        `Customer: ${customerName} (${order.phone || '-'})\n` +
        `Reason: ${reasonText || reasonCode}\n\n` +
        `Review required in the KAAPAV order workflow.`
      );
    } catch (
      notificationError
    ) {
      console.error(
        'RETURN_OWNER_NOTIFICATION_FAILED',
        requestId,
        notificationError?.message ||
        notificationError
      );
    }
  }

  const createdRequest =
    await env.DB.prepare(`
      SELECT *
      FROM return_requests
      WHERE request_id = ?
    `)
      .bind(requestId)
      .first();

  const {
    results: createdItems,
  } =
    await env.DB.prepare(`
      SELECT *
      FROM return_request_items
      WHERE request_id = ?
      ORDER BY line_index ASC
    `)
      .bind(requestId)
      .all();

  return jsonResponse(
    {
      success: true,
      request: {
        ...createdRequest,

        evidence_urls:
          parseReturnJsonArray(
            createdRequest
              ?.evidence_urls_json
          ),

        items:
          createdItems || [],
      },

      returnWindow: {
        days:
          CUSTOMER_RETURN_WINDOW_DAYS,

        expiresAt:
          eligibility.expiresAt,
      },
    },
    201
  );
}

async function handleReviewReturnQc(
  orderId,
  requestId,
  request,
  env
) {
  const body = await request
    .json()
    .catch(() => ({}));

  const decision = cleanReturnText(
    body.decision,
    20
  ).toLowerCase();

  if (
    decision !== 'passed' &&
    decision !== 'failed'
  ) {
    return errorResponse(
      'decision must be passed or failed',
      400
    );
  }

  const ownerNote = cleanReturnText(
    body.owner_note,
    2000
  );

  if (
    decision === 'failed' &&
    !ownerNote
  ) {
    return errorResponse(
      'QC failure reason is required',
      400
    );
  }

  const returnRequest =
    await env.DB.prepare(`
      SELECT
        rr.*,
        o.customer_name AS order_customer_name,
        o.phone AS order_phone
      FROM return_requests rr
      INNER JOIN orders o
        ON o.order_id = rr.order_id
      WHERE rr.order_id = ?
        AND rr.request_id = ?
      LIMIT 1
    `)
      .bind(
        orderId,
        requestId
      )
      .first();

  if (!returnRequest) {
    return errorResponse(
      'Return request not found',
      404
    );
  }

  const currentStatus = String(
    returnRequest.status || ''
  ).toLowerCase();

  if (currentStatus !== 'received') {
    return errorResponse(
      `Only received requests can complete quality inspection. ` +
      `Current status: ${currentStatus || 'unknown'}`,
      409
    );
  }

  const nextStatus =
    decision === 'passed'
      ? 'qc_passed'
      : 'qc_failed';

  const qcNote = ownerNote
    ? `QC ${decision}: ${ownerNote}`
    : `QC ${decision}`;

  const updateResult =
    await env.DB.prepare(`
      UPDATE return_requests
      SET
        status = ?,
        qc_completed_at = datetime('now'),

        owner_note = CASE
          WHEN ? != ''
          THEN CASE
            WHEN COALESCE(owner_note, '') = ''
            THEN ?
            ELSE owner_note || char(10) || ?
          END
          ELSE owner_note
        END,

        updated_at = datetime('now')
      WHERE order_id = ?
        AND request_id = ?
        AND status = 'received'
    `)
      .bind(
        nextStatus,
        qcNote,
        qcNote,
        qcNote,
        orderId,
        requestId
      )
      .run();

  if (
    Number(
      updateResult?.meta?.changes || 0
    ) !== 1
  ) {
    return errorResponse(
      'Return request changed before quality inspection completed. Refresh and retry.',
      409
    );
  }

  const requestType = String(
    returnRequest.request_type ||
    'return'
  ).toLowerCase();

  const typeLabel =
    requestType === 'exchange'
      ? 'Exchange'
      : 'Return';

  await logOrderEvent(
    env,
    orderId,
    `${requestType}_${nextStatus}`,
    `${typeLabel} request ${requestId} quality inspection ${decision}`,
    {
      requestId,
      previousStatus: currentStatus,
      status: nextStatus,
      decision,
      ownerNote,
    },
    'admin'
  );

  const customerPhone =
    cleanReturnText(
      returnRequest.order_phone ||
      returnRequest.phone,
      30
    );

  if (customerPhone) {
    const customerName =
      cleanReturnText(
        returnRequest.order_customer_name ||
        returnRequest.customer_name ||
        'Customer',
        300
      );

    const message =
      decision === 'passed'
        ? (
            `*${typeLabel} Quality Check Passed*\n\n` +
            `Hi ${customerName},\n\n` +
            `Order: *${orderId}*\n` +
            `Request ID: *${requestId}*\n` +
            `Status: QC Passed\n\n` +
            `Your returned package has passed inspection. ` +
            `The next refund or exchange action requires separate owner confirmation.\n\n` +
            `No refund or exchange shipment has been started automatically.\n\n` +
            `KAAPAV Fashion Jewellery`
          )
        : (
            `*${typeLabel} Quality Check Update*\n\n` +
            `Hi ${customerName},\n\n` +
            `Order: *${orderId}*\n` +
            `Request ID: *${requestId}*\n` +
            `Status: QC Needs Review\n\n` +
            `The returned package could not be approved during inspection. ` +
            `Our team will review the case and contact you.\n\n` +
            `No refund or exchange shipment has been started automatically.\n\n` +
            `KAAPAV Fashion Jewellery`
          );

    try {
      await sendWhatsAppText(
        env,
        customerPhone,
        message
      );
    } catch (notificationError) {
      console.error(
        'RETURN_QC_NOTIFICATION_FAILED',
        requestId,
        notificationError?.message ||
        notificationError
      );
    }
  }

  const updatedRequest =
    await env.DB.prepare(`
      SELECT *
      FROM return_requests
      WHERE order_id = ?
        AND request_id = ?
      LIMIT 1
    `)
      .bind(
        orderId,
        requestId
      )
      .first();

  return jsonResponse({
    success: true,
    decision,
    status: nextStatus,
    request: updatedRequest,
  });
}

async function handleProcessReturnRefund(
  orderId,
  requestId,
  request,
  env
) {
  const body = await request
    .json()
    .catch(() => ({}));

  const deductFee =
    body.deduct_reverse_shipping_fee === true;

  const previewOnly =
    body.preview_only === true;

  const ownerNote = cleanReturnText(
    body.owner_note,
    2000
  );

  const row = await env.DB.prepare(`
    SELECT
      rr.*,
      o.total AS order_total,
      o.subtotal AS order_subtotal,
      o.discount AS order_discount,
      o.payment_status AS order_payment_status,
      o.payment_id AS order_payment_id,
      o.customer_name AS order_customer_name,
      o.phone AS order_phone
    FROM return_requests rr
    JOIN orders o
      ON o.order_id = rr.order_id
    WHERE rr.order_id = ?
      AND rr.request_id = ?
    LIMIT 1
  `)
    .bind(
      orderId,
      requestId
    )
    .first();

  if (!row) {
    return errorResponse(
      'Return request not found',
      404
    );
  }

  if (
    String(
      row.request_type || ''
    ).toLowerCase() !== 'return'
  ) {
    return errorResponse(
      'Only return requests can be refunded. Use the exchange workflow for exchanges.',
      409
    );
  }

  const savedRefundStatus = String(
    row.refund_status ||
    'not_started'
  ).toLowerCase();

  if (
    savedRefundStatus === 'processed' &&
    row.refund_id
  ) {
    return jsonResponse({
      success: true,
      alreadyProcessed: true,
      status: row.status,
      refundStatus: savedRefundStatus,
      refundId: row.refund_id,
      amount: Number(
        row.refund_amount || 0
      ),
    });
  }

  const currentStatus = String(
    row.status || ''
  ).toLowerCase();

  if (currentStatus !== 'qc_passed') {
    return errorResponse(
      `Only QC-passed returns can be refunded. ` +
      `Current status: ${currentStatus || 'unknown'}`,
      409
    );
  }

  if (
    String(
      row.order_payment_status || ''
    ).toLowerCase() !== 'paid'
  ) {
    return errorResponse(
      'Order payment is not eligible for refund',
      409
    );
  }

  const paymentId = cleanReturnText(
    row.payment_id ||
    row.order_payment_id,
    200
  );

  if (!paymentId.startsWith('pay_')) {
    return errorResponse(
      'A Razorpay payment ID is required. COD or offline refunds must be handled manually.',
      409
    );
  }

  const totals = await env.DB.prepare(`
    SELECT
      COALESCE(
        SUM(
          quantity *
          unit_price
        ),
        0
      ) AS selected_gross
    FROM return_request_items
    WHERE order_id = ?
      AND request_id = ?
  `)
    .bind(
      orderId,
      requestId
    )
    .first();

  const selectedGross = Math.round(
    Number(
      totals?.selected_gross || 0
    ) * 100
  ) / 100;

  if (
    !Number.isFinite(selectedGross) ||
    selectedGross <= 0
  ) {
    return errorResponse(
      'Return item value is unavailable',
      409
    );
  }

  const orderSubtotal = Math.max(
    selectedGross,
    Number(
      row.order_subtotal || 0
    )
  );

  const orderDiscount = Math.max(
    0,
    Number(
      row.order_discount || 0
    )
  );

  const allocatedDiscount =
    orderSubtotal > 0
      ? Math.round(
          Math.min(
            orderDiscount,
            orderDiscount *
            (
              selectedGross /
              orderSubtotal
            )
          ) * 100
        ) / 100
      : 0;

  const refundableItemValue = Math.max(
    0,
    Math.round(
      (
        selectedGross -
        allocatedDiscount
      ) * 100
    ) / 100
  );

  const reverseFee = Math.max(
    0,
    Number(
      row.reverse_shipping_fee ??
      60
    )
  );

  const deductionAmount =
    deductFee
      ? Math.round(
          reverseFee * 100
        ) / 100
      : 0;

  const refundAmount = Math.round(
    (
      refundableItemValue -
      deductionAmount
    ) * 100
  ) / 100;

  if (refundAmount < 1) {
    return errorResponse(
      'Final Razorpay refund must be at least ₹1 after deduction',
      409
    );
  }

  const orderTotal = Math.max(
    0,
    Number(
      row.order_total || 0
    )
  );

  if (
    orderTotal > 0 &&
    refundAmount > orderTotal
  ) {
    return errorResponse(
      'Calculated refund exceeds the paid total',
      409
    );
  }

  if (previewOnly) {
    return jsonResponse({
      success: true,
      preview: true,
      requestId,
      selectedGross,
      allocatedDiscount,
      refundableItemValue,
      reverseShippingFee: reverseFee,
      reverseShippingDeducted:
        deductFee,
      deductionAmount,
      amount: refundAmount,
      currency: 'INR',
    });
  }

  const amountPaise = Math.round(
  refundAmount * 100
);

const savedKey = cleanReturnText(
  row.refund_idempotency_key,
  100
);

if (
  savedKey &&
  Math.abs(
    Number(
      row.refund_amount || 0
    ) -
    refundAmount
  ) > 0.001
) {
  return errorResponse(
    'Refund amount cannot change while the existing Razorpay request is being retried',
    409
  );
}

const generatedKey = (
  `KRF_${requestId}_` +
  `${Date.now()}_` +
  `${crypto.randomUUID()}`
)
  .replace(
    /[^A-Za-z0-9_-]/g,
    '_'
  )
  .slice(0, 100);

const idempotencyKey =
  savedKey || generatedKey;

const retryingSameRefund =
  savedKey.length > 0;

  const note = ownerNote
    ? `Refund initiated: ${ownerNote}`
    : 'Refund initiated';

  const claim = await env.DB.prepare(`
    UPDATE return_requests
    SET
      refund_amount = ?,
      refund_idempotency_key = ?,
      refund_status = 'processing',
      refund_gateway = 'razorpay',
      refund_method = 'original_payment',
      refund_currency = 'INR',
      refund_speed_requested = 'normal',
      refund_failure_reason = '',
      refund_failed_at = NULL,

      refund_initiated_at =
        COALESCE(
          refund_initiated_at,
          datetime('now')
        ),

      approved_by = CASE
        WHEN COALESCE(
          approved_by,
          ''
        ) = ''
        THEN 'owner'
        ELSE approved_by
      END,

      owner_note = CASE
        WHEN ? = ''
        THEN owner_note

        WHEN COALESCE(
          owner_note,
          ''
        ) = ''
        THEN ?

        ELSE
          owner_note ||
          char(10) ||
          ?
      END,

      updated_at = datetime('now')

    WHERE order_id = ?
      AND request_id = ?
      AND status = 'qc_passed'
      AND refund_id IS NULL

      AND refund_status IN (
        'not_started',
        'failed',
        'processing'
      )

      AND (
        refund_idempotency_key IS NULL OR
        refund_idempotency_key = ?
      )
  `)
    .bind(
      refundAmount,
      idempotencyKey,
      note,
      note,
      note,
      orderId,
      requestId,
      idempotencyKey
    )
    .run();

  if (
    Number(
      claim?.meta?.changes || 0
    ) !== 1
  ) {
    return errorResponse(
      'Return refund state changed. Refresh and retry.',
      409
    );
  }

  try {
    const refund =
      await processRazorpayRefund(
        env,
        paymentId,
        refundAmount,
        orderId,
        {
          requestId,
          idempotencyKey,
          reverseShippingDeducted:
            deductFee,
          verifyPayment:
            !retryingSameRefund,
        }
      );

    const refundStatus = String(
      refund.status || 'pending'
    ).toLowerCase();

    if (refundStatus === 'failed') {
      throw new Error(
        'Razorpay returned a failed refund status'
      );
    }

    const processed =
      refundStatus === 'processed';

    const requestStatus =
      processed
        ? 'refunded'
        : 'refund_pending';

    const acquirer =
      refund.acquirer_data || {};

    const referenceType =
      acquirer.arn
        ? 'arn'
        : acquirer.rrn
          ? 'rrn'
          : acquirer.utr
            ? 'utr'
            : null;

    const reference =
      acquirer.arn ||
      acquirer.rrn ||
      acquirer.utr ||
      null;

    await env.DB.prepare(`
      UPDATE return_requests
      SET
        status = ?,
        refund_id = ?,
        refund_status = ?,
        refund_speed_requested = ?,
        refund_speed_processed = ?,
        refund_acquirer_reference = ?,
        refund_acquirer_reference_type = ?,

        refund_processed_at = CASE
          WHEN ? = 'processed'
          THEN datetime('now')
          ELSE refund_processed_at
        END,

        completed_at = CASE
          WHEN ? = 'processed'
          THEN datetime('now')
          ELSE completed_at
        END,

        updated_at = datetime('now')

      WHERE order_id = ?
        AND request_id = ?
        AND refund_idempotency_key = ?
    `)
      .bind(
        requestStatus,
        cleanReturnText(
          refund.id,
          200
        ) || null,
        refundStatus,
        cleanReturnText(
          refund.speed_requested ||
          'normal',
          50
        ),
        cleanReturnText(
          refund.speed_processed,
          50
        ) || null,
        reference,
        referenceType,
        refundStatus,
        refundStatus,
        orderId,
        requestId,
        idempotencyKey
      )
      .run();

    await env.DB.prepare(`
      INSERT OR IGNORE INTO return_refund_events (
        event_id,
        request_id,
        order_id,
        payment_id,
        refund_id,
        event_type,
        refund_status,
        amount,
        currency,
        acquirer_reference,
        acquirer_reference_type,
        payload_json,
        processing_status,
        error_message,
        received_at,
        processed_at
      ) VALUES (
        ?, ?, ?, ?, ?,
        'refund.api_response',
        ?, ?, 'INR',
        ?, ?, ?,
        'processed',
        '',
        datetime('now'),
        datetime('now')
      )
    `)
      .bind(
        `refund_api_${refund.id || idempotencyKey}`,
        requestId,
        orderId,
        paymentId,
        cleanReturnText(
          refund.id,
          200
        ) || null,
        refundStatus,
        refundAmount,
        reference,
        referenceType,
        JSON.stringify(refund)
      )
      .run();

    if (processed) {
      const refundTotals =
        await env.DB.prepare(`
          SELECT
            COALESCE(
              SUM(refund_amount),
              0
            ) AS refunded_total
          FROM return_requests
          WHERE order_id = ?
            AND refund_status = 'processed'
        `)
          .bind(orderId)
          .first();

      const fullyRefunded =
        orderTotal > 0 &&
        Number(
          refundTotals?.refunded_total ||
          0
        ) + 0.001 >= orderTotal;

      if (fullyRefunded) {
        await env.DB.prepare(`
          UPDATE orders
          SET
            payment_status = 'refunded',
            updated_at = datetime('now')
          WHERE order_id = ?
        `)
          .bind(orderId)
          .run();
      }
    }

    await logOrderEvent(
      env,
      orderId,
      processed
        ? 'return_refund_processed'
        : 'return_refund_pending',
      `Return request ${requestId} ` +
      `refund ${refundStatus}: ` +
      `₹${refundAmount.toFixed(2)}`,
      {
        requestId,
        refundId:
          refund.id || '',
        selectedGross,
        allocatedDiscount,
        refundableItemValue,
        reverseShippingDeducted:
          deductFee,
        deductionAmount,
        refundAmount,
      },
      'admin'
    );

    try {
      await sendWhatsAppText(
        env,
        row.order_phone ||
        row.phone,
        `*Return Refund ${processed ? 'Processed' : 'Initiated'}*\n\n` +
        `Order: *${orderId}*\n` +
        `Request ID: *${requestId}*\n` +
        `Refund amount: *₹${refundAmount.toFixed(2)}*\n` +
        `Reverse shipping deduction: *₹${deductionAmount.toFixed(2)}*\n` +
        `Refund ID: *${refund.id || 'Pending'}*\n\n` +
        `Refund is being returned to the original payment method.\n\n` +
        `KAAPAV Fashion Jewellery`
      );
    } catch (
      notificationError
    ) {
      console.error(
        'RETURN_REFUND_NOTIFICATION_FAILED',
        requestId,
        notificationError?.message ||
        notificationError
      );
    }

    return jsonResponse({
      success: true,
      status: requestStatus,
      refundStatus,
      refundId:
        refund.id || null,
      selectedGross,
      allocatedDiscount,
      refundableItemValue,
      reverseShippingDeducted:
        deductFee,
      deductionAmount,
      amount: refundAmount,
    });
  } catch (error) {
    const reason = cleanReturnText(
      error?.message || error,
      2000
    );

    await env.DB.prepare(`
      UPDATE return_requests
      SET
        refund_status = 'failed',
        refund_failure_reason = ?,
        refund_failed_at = datetime('now'),
        updated_at = datetime('now')
      WHERE order_id = ?
        AND request_id = ?
        AND refund_idempotency_key = ?
        AND refund_id IS NULL
    `)
      .bind(
        reason,
        orderId,
        requestId,
        idempotencyKey
      )
      .run();

    await logOrderEvent(
      env,
      orderId,
      'return_refund_failed',
      `Return request ${requestId} refund failed`,
      {
        requestId,
        refundAmount,
        reverseShippingDeducted:
          deductFee,
        deductionAmount,
        error: reason,
      },
      'admin'
    );

    return errorResponse(
      `Refund failed: ${reason}`,
      502
    );
  }
}

