async function handleGetOrderReturnRequests(
  orderId,
  env
) {
  const order = await env.DB.prepare(`
    SELECT order_id
    FROM orders
    WHERE order_id = ?
    LIMIT 1
  `).bind(orderId).first();

  if (!order) {
    return errorResponse(
      'Order not found',
      404
    );
  }

  const { results: requests } =
    await env.DB.prepare(`
      SELECT *
      FROM return_requests
      WHERE order_id = ?
      ORDER BY id DESC
    `).bind(orderId).all();

  const { results: items } =
    await env.DB.prepare(`
      SELECT *
      FROM return_request_items
      WHERE order_id = ?
      ORDER BY request_id, line_index
    `).bind(orderId).all();

  const itemsByRequest = new Map();

  for (const item of items || []) {
    const current =
      itemsByRequest.get(
        item.request_id
      ) || [];

    current.push({
      ...item,
      evidence_urls:
        parseReturnJsonArray(
          item.evidence_urls_json
        ),
    });

    itemsByRequest.set(
      item.request_id,
      current
    );
  }

  const packedRequests =
    (requests || []).map(
      (returnRequest) => ({
        ...returnRequest,
        evidence_urls:
          parseReturnJsonArray(
            returnRequest
              .evidence_urls_json
          ),
        items:
          itemsByRequest.get(
            returnRequest.request_id
          ) || [],
      })
    );

  return jsonResponse({
    success: true,
    requests: packedRequests,
    total: packedRequests.length,
  });
}

