async function handleCreateCoupon(request, env) {
  const body = await request.json().catch(() => ({}));

  let record;

  try {
    record = buildCouponRecord(body);
  } catch (error) {
    return errorResponse(error.message, 400);
  }

  const existing = await env.DB.prepare(`
    SELECT id
    FROM coupons
    WHERE UPPER(code) = ?
    LIMIT 1
  `).bind(record.code).first();

  if (existing) {
    return errorResponse(
      'Offer code already exists',
      409
    );
  }

  const result = await env.DB.prepare(`
    INSERT INTO coupons (
      code,
      type,
      value,
      min_order,
      max_discount,
      usage_limit,
      used_count,
      starts_at,
      expires_at,
      is_active,
      created_at
    )
    VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?, ?, datetime('now'))
  `).bind(
    record.code,
    record.type,
    record.value,
    record.minOrder,
    record.maxDiscount,
    record.usageLimit,
    record.startsAt,
    record.expiresAt,
    record.isActive
  ).run();

  const coupon = await env.DB.prepare(`
    SELECT *
    FROM coupons
    WHERE id = ?
  `).bind(result.meta.last_row_id).first();

  return jsonResponse({
    success: true,
    coupon,
  });
}

async function handleUpdateCoupon(
  id,
  request,
  env
) {
  const existing = await env.DB.prepare(`
    SELECT *
    FROM coupons
    WHERE id = ?
  `).bind(id).first();

  if (!existing) {
    return errorResponse('Offer not found', 404);
  }

  const body = await request.json().catch(() => ({}));

  let record;

  try {
    record = buildCouponRecord(body, existing);
  } catch (error) {
    return errorResponse(error.message, 400);
  }

  const duplicate = await env.DB.prepare(`
    SELECT id
    FROM coupons
    WHERE UPPER(code) = ?
      AND id != ?
    LIMIT 1
  `).bind(record.code, id).first();

  if (duplicate) {
    return errorResponse(
      'Offer code already exists',
      409
    );
  }

  await env.DB.prepare(`
    UPDATE coupons
    SET
      code = ?,
      type = ?,
      value = ?,
      min_order = ?,
      max_discount = ?,
      usage_limit = ?,
      starts_at = ?,
      expires_at = ?,
      is_active = ?
    WHERE id = ?
  `).bind(
    record.code,
    record.type,
    record.value,
    record.minOrder,
    record.maxDiscount,
    record.usageLimit,
    record.startsAt,
    record.expiresAt,
    record.isActive,
    id
  ).run();

  const coupon = await env.DB.prepare(`
    SELECT *
    FROM coupons
    WHERE id = ?
  `).bind(id).first();

  return jsonResponse({
    success: true,
    coupon,
  });
}

