async function handleCustomerOrderReturnRequests(
  request,
  env,
  orderId
) {
  const context =
    await getCustomerOrderContext(
      request,
      env,
      orderId
    );

  if (!context.authenticated) {
    return errorResponse(
      'Unauthorized',
      401
    );
  }

  if (!context.order) {
    return errorResponse(
      'Order not found',
      404
    );
  }

  if (
    request.method === 'POST'
  ) {
    const body =
      await request
        .json()
        .catch(() => ({}));

    const safeItems =
      Array.isArray(body.items)
        ? body.items
            .slice(0, 50)
            .map(
              (item) => ({
                line_index:
                  item?.line_index,

                sku:
                  item?.sku,

                quantity:
                  item?.quantity ??
                  item?.qty,

                replacement_sku:
                  item
                    ?.replacement_sku,

                replacement_name:
                  item
                    ?.replacement_name,

                condition_note:
                  item
                    ?.condition_note,

                evidence_urls:
                  item
                    ?.evidence_urls,
              })
            )
        : [];

    const safeBody = {
      request_type:
        body.request_type,

      request_scope:
        body.request_scope,

      reason_code:
        body.reason_code,

      reason_text:
        body.reason_text,

      customer_note:
        body.customer_note,

      evidence_urls:
        body.evidence_urls,

      items:
        safeItems,

      reverse_shipping_fee:
        60,

      owner_override:
        false,
    };

    return handleCreateReturnRequest(
      context.order.order_id,
      request,
      env,
      {
        body:
          safeBody,

        order:
          context.order,

        eventSource:
          'customer',

        allowOwnerOverride:
          false,

        fixedReverseShippingFee:
          60,

        notifyCustomer:
          true,
      }
    );
  }

  const {
    results: requests,
  } =
    await env.DB.prepare(`
      SELECT
        request_id,
        order_id,
        request_type,
        request_scope,
        reason_code,
        reason_text,
        customer_note,
        status,
        reverse_shipping_fee,
        refund_amount,
        price_difference,
        refund_status,
        requested_at,
        approved_at,
        rejected_at,
        pickup_scheduled_at,
        picked_up_at,
        received_at,
        qc_completed_at,
        refund_processed_at,
        refund_failed_at,
        completed_at,
        created_at,
        updated_at
      FROM return_requests
      WHERE order_id = ?
      ORDER BY id DESC
    `)
      .bind(
        context.order.order_id
      )
      .all();

  const {
    results: itemRows,
  } =
    await env.DB.prepare(`
      SELECT
        request_id,
        line_index,
        sku,
        product_name,
        quantity,
        unit_price,
        replacement_sku,
        replacement_name,
        condition_note,
        created_at,
        updated_at
      FROM return_request_items
      WHERE order_id = ?
      ORDER BY
        request_id,
        line_index
    `)
      .bind(
        context.order.order_id
      )
      .all();

  const itemsByRequest =
    new Map();

  for (
    const item of itemRows || []
  ) {
    const current =
      itemsByRequest.get(
        item.request_id
      ) || [];

    current.push(item);

    itemsByRequest.set(
      item.request_id,
      current
    );
  }

  const packedRequests =
    (requests || []).map(
      (returnRequest) =>
        packCustomerReturnRequest(
          returnRequest,
          itemsByRequest.get(
            returnRequest.request_id
          ) || []
        )
    );

  const latestRequest =
    packedRequests[0] || null;

  const eligibility =
    getPurchaseReturnEligibility(
      context.order
    );

  const hasOpenRequest =
    isOpenReturnRequestStatus(
      latestRequest?.status
    );

  return jsonResponse({
    success: true,

    orderId:
      context.order.order_id,

    requests:
      packedRequests,

    total:
      packedRequests.length,

    latestRequest,

    returnEligibility: {
      eligible:
        eligibility.eligible &&
        !hasOpenRequest,

      windowDays:
        CUSTOMER_RETURN_WINDOW_DAYS,

      expiresAt:
        eligibility.expiresAt,

      daysRemaining:
        eligibility.daysRemaining,

      reason:
        hasOpenRequest
          ? 'An active return or exchange request already exists'
          : eligibility.reason,

      code:
        hasOpenRequest
          ? 'active_request_exists'
          : eligibility.code,
    },
  });
}

